import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { resolve } from 'node:path';

/** Make sure the synthetic guitar fixtures exist (generated by `taber synth`, not committed). */
export default function globalSetup() {
  const root = resolve(import.meta.dirname, '../../..');
  const out = resolve(root, 'ml/eval/synthetic');
  for (const name of ['box_techniques', 'a_minor_lick', 'fast_run']) {
    if (existsSync(resolve(out, `${name}.mix.wav`))) continue;
    execFileSync('uv', ['run', '--no-sync', 'taber', 'synth', resolve(out, `${name}.tab.json`), '-o', out, '--backing', '0'], {
      cwd: root,
      env: { ...process.env, UV_PROJECT_ENVIRONMENT: process.env.UV_PROJECT_ENVIRONMENT ?? `${process.env.HOME}/.cache/taber/venv` },
      stdio: 'inherit',
    });
  }
  // a video take: ffmpeg test pattern + the synthetic guitar as its sound track
  const mp4 = resolve(out, 'box_techniques.mp4');
  if (!existsSync(mp4)) {
    execFileSync('ffmpeg', ['-v', 'error', '-y', '-f', 'lavfi', '-i', 'testsrc=size=640x360:rate=30', '-i', resolve(out, 'box_techniques.wav'),
      '-shortest', '-c:v', 'mpeg4', '-q:v', '5', '-c:a', 'aac', mp4], { stdio: 'inherit' });
  }
}
